import Foundation

// MARK: - Knowing God Theme Content (20 Entries)

extension ContentLibrary {

    static let knowingGodThemeContent: [DayContent] = [
        DayContent(
            scriptureReference: "Jeremiah 9:23-24",
            scriptureText: "Let not the wise boast of their wisdom or the strong boast of their strength or the rich boast of their riches, but let the one who boasts boast about this: that they have the understanding to know me, that I am the Lord, who exercises kindness, justice and righteousness on earth, for in these I delight.",
            devotionalTitle: "The Only Thing Worth Boasting About",
            devotionalText: "God says the greatest achievement isn't wisdom, strength, or wealth — it's knowing Him. Not knowing about Him, but actually understanding His character: kindness, justice, righteousness. These aren't abstract qualities. They're how God shows up every day. When you know what God delights in, you begin to delight in the same things.",
            prayerText: "Lord, I want to know You — not just facts about You, but Your heart, Your character, Your delights. Show me Your kindness, justice, and righteousness today. Let knowing You be my greatest pursuit and my deepest joy. In Jesus' name, amen.",
            reflectionPrompt: "If someone asked you to describe God's character in three words, what would you say?",
            actionSteps: ["Write down three things you know about God's character from personal experience", "Ask God to reveal one new aspect of His nature to you today"]
        ),
        DayContent(
            scriptureReference: "Psalm 46:10",
            scriptureText: "He says, 'Be still, and know that I am God; I will be exalted among the nations, I will be exalted in the earth.'",
            devotionalTitle: "Stillness Is How You Know",
            devotionalText: "Knowing God requires stillness — not just physical quiet, but a settled heart. In our noisy, busy lives, God's invitation to 'be still' is radical. It's in the stillness that you move from knowing about God to knowing God. He doesn't compete with your noise. He waits for your attention.",
            prayerText: "Lord, quiet my heart. I stop striving and recognize that You are God. In this stillness, reveal Yourself to me. Help me make space for You in my crowded days. I want to know You, not just rush past You. In Jesus' name, amen.",
            reflectionPrompt: "When was the last time you were truly still before God?",
            actionSteps: ["Set a timer for 10 minutes of complete silence and just be with God", "Turn off all notifications for one hour today and use that space to listen"]
        ),
        DayContent(
            scriptureReference: "Philippians 3:8-10",
            scriptureText: "What is more, I consider everything a loss because of the surpassing worth of knowing Christ Jesus my Lord, for whose sake I have lost all things. I consider them garbage, that I may gain Christ and be found in him.",
            devotionalTitle: "Worth More Than Everything",
            devotionalText: "Paul had an impressive resume — education, status, religious credentials. He called it all garbage compared to knowing Christ. That's not despair; that's a man who found something so valuable that everything else paled in comparison. Knowing Jesus isn't one priority among many. It's the priority that redefines all the others.",
            prayerText: "Jesus, I want to know You with the passion Paul had. Help me see that knowing You is worth more than any achievement, possession, or status. Rearrange my priorities until You are truly first. I want to gain You above all else. In Jesus' name, amen.",
            reflectionPrompt: "What would you need to let go of to pursue knowing Christ more deeply?",
            actionSteps: ["Identify one thing competing with your time with God and take a step back from it this week", "Read Philippians 3:1-14 and journal about what Paul's passion stirs in you"]
        ),
        DayContent(
            scriptureReference: "John 17:3",
            scriptureText: "Now this is eternal life: that they know you, the only true God, and Jesus Christ, whom you have sent.",
            devotionalTitle: "Eternal Life Starts Now",
            devotionalText: "Jesus defines eternal life not as living forever in heaven, but as knowing God. That means eternal life isn't just a future destination — it's a present relationship. Every moment you spend getting to know God, you're experiencing eternal life right now. Heaven doesn't start when you die. It starts when you know Him.",
            prayerText: "Father, I want to experience eternal life today — not someday, but now. Deepen my knowledge of You. Help me see that knowing You isn't preparation for eternal life; it IS eternal life. I don't want to wait for heaven to know You deeply. In Jesus' name, amen.",
            reflectionPrompt: "How does knowing that eternal life is about relationship change your view of your daily walk with God?",
            actionSteps: ["Spend 15 minutes today focused solely on getting to know God better through prayer or Scripture", "Tell someone that eternal life is knowing God, not just going to heaven"]
        ),
        DayContent(
            scriptureReference: "Exodus 34:6-7",
            scriptureText: "And he passed in front of Moses, proclaiming, 'The Lord, the Lord, the compassionate and gracious God, slow to anger, abounding in love and faithfulness, maintaining love to thousands, and forgiving wickedness, rebellion and sin.'",
            devotionalTitle: "God's Self-Description",
            devotionalText: "When God describes Himself, He leads with compassion and grace. Not power. Not authority. Not judgment. Compassion. This is how God wants to be known — as the One who is slow to anger and overflowing with love. If your image of God doesn't match His self-description, it's your image that needs updating.",
            prayerText: "Lord, I receive Your self-description today. You are compassionate, gracious, slow to anger, and abounding in love. Where my image of You has been distorted by fear or religion, correct it with Your own words. I want to know You as You truly are. In Jesus' name, amen.",
            reflectionPrompt: "Does your mental picture of God match His self-description in Exodus 34? Where is it different?",
            actionSteps: ["Write out Exodus 34:6-7 and put it somewhere you'll see it daily", "Replace one wrong belief about God with His own words about Himself"]
        ),
        DayContent(
            scriptureReference: "Romans 1:20",
            scriptureText: "For since the creation of the world God's invisible qualities — his eternal power and divine nature — have been clearly seen, being understood from what has been made, so that people are without excuse.",
            devotionalTitle: "God Speaks Through Creation",
            devotionalText: "Creation is God's first revelation. His power is seen in thunderstorms and galaxies. His creativity shows in a thousand species of beetles. His attention to detail appears in snowflakes and DNA. You don't need a Bible to start knowing God — just open your eyes. Nature is a daily sermon about who God is.",
            prayerText: "Creator God, open my eyes to see You in what You've made. Show me Your power in the sky, Your creativity in the earth, Your care in the smallest details. Let creation teach me about Your character today. I don't want to walk past Your handiwork without seeing You in it. In Jesus' name, amen.",
            reflectionPrompt: "What aspect of creation most reveals God's character to you?",
            actionSteps: ["Spend 10 minutes outdoors today intentionally looking for God's qualities in nature", "Thank God for three specific things in creation that reveal something about Him"]
        ),
        DayContent(
            scriptureReference: "Hebrews 1:3",
            scriptureText: "The Son is the radiance of God's glory and the exact representation of his being, sustaining all things by his powerful word.",
            devotionalTitle: "Jesus Is God Made Visible",
            devotionalText: "Want to know what God is like? Look at Jesus. He is the exact representation of God's being — not an approximation, not a partial picture, but the full image. When Jesus showed compassion, that's God's compassion. When Jesus wept, that's God's heart. When Jesus forgave, that's God's nature. Knowing Jesus is knowing God.",
            prayerText: "Jesus, You are the exact image of the Father. When I see You, I see God. Help me study Your life — Your words, Your actions, Your heart — and in doing so, know the Father more deeply. You are the clearest picture of God I will ever see. In Jesus' name, amen.",
            reflectionPrompt: "What moment in Jesus' life most clearly shows you what God is like?",
            actionSteps: ["Read one chapter from the Gospels today and write down what it reveals about God's character", "When you think about God, picture Jesus — His face, His hands, His compassion"]
        ),
        DayContent(
            scriptureReference: "Psalm 139:1-4",
            scriptureText: "You have searched me, Lord, and you know me. You know when I sit and when I rise; you perceive my thoughts from afar. You discern my going out and my lying down; you are familiar with all my ways.",
            devotionalTitle: "Known Before You Know",
            devotionalText: "Before you ever started knowing God, He already knew everything about you. Every thought, every habit, every hidden thing. And He still chose you. Knowing God isn't a one-way pursuit — it's a response to being already fully known. The God who knows your worst moments still invites you closer. That's the kind of God you're getting to know.",
            prayerText: "Lord, You know me completely — every thought, every fear, every secret. And You still love me. Help me rest in being fully known by You. Take away the fear of being seen and replace it with the comfort of being understood by a God who loves me anyway. In Jesus' name, amen.",
            reflectionPrompt: "How does it feel to know that God already knows everything about you?",
            actionSteps: ["Read all of Psalm 139 slowly and let each verse sink in", "Tell God one thing you've been trying to hide, knowing He already knows"]
        ),
        DayContent(
            scriptureReference: "1 John 4:8",
            scriptureText: "Whoever does not love does not know God, because God is love.",
            devotionalTitle: "God Doesn't Just Love — He IS Love",
            devotionalText: "God doesn't just have love or show love — He IS love. Love isn't something God does; it's who He is. Every interaction with God is an interaction with love itself. And knowing God transforms you into a more loving person. If you want to know whether you're growing in your knowledge of God, check your love. They're inseparable.",
            prayerText: "God, You are love. Not just loving — love itself. Help me understand what that means. Let my growing knowledge of You overflow into growing love for others. If I know You but don't love, I've missed the point. Transform my knowledge into love. In Jesus' name, amen.",
            reflectionPrompt: "Is your knowledge of God producing more love in you? How can you tell?",
            actionSteps: ["Show love to one person today as an expression of your knowledge of God", "Reflect on how your understanding of God's love has changed over time"]
        ),
        DayContent(
            scriptureReference: "Deuteronomy 7:9",
            scriptureText: "Know therefore that the Lord your God is God; he is the faithful God, keeping his covenant of love to a thousand generations of those who love him and keep his commandments.",
            devotionalTitle: "A Thousand Generations of Faithfulness",
            devotionalText: "God's faithfulness isn't short-term. It spans a thousand generations. That means the same God who was faithful to Abraham is faithful to you. He doesn't change, doesn't break promises, doesn't grow tired of keeping His word. When you know God's faithfulness, you can trust Him with your future.",
            prayerText: "Lord, You are the faithful God. Your covenant love extends a thousand generations. Help me trust in Your unchanging faithfulness today. What You promised, You will do. What You started, You will finish. I rest in a God who never breaks His word. In Jesus' name, amen.",
            reflectionPrompt: "How has God's faithfulness shown up in your life or your family's history?",
            actionSteps: ["Write down three examples of God's faithfulness in your life", "Share a story of God's faithfulness with someone younger"]
        ),
        DayContent(
            scriptureReference: "Isaiah 55:8-9",
            scriptureText: "'For my thoughts are not your thoughts, neither are your ways my ways,' declares the Lord. 'As the heavens are higher than the earth, so are my ways higher than your ways and my thoughts than your thoughts.'",
            devotionalTitle: "Higher Than You Think",
            devotionalText: "Knowing God includes accepting that you'll never fully comprehend Him. His thoughts are higher than yours. His ways are beyond your understanding. This isn't frustrating — it's actually comforting. You don't need a God you can fully figure out. You need a God who is bigger than your problems, wiser than your plans, and higher than your highest thoughts.",
            prayerText: "Lord, Your thoughts are higher than mine. Your ways are beyond my understanding. Instead of being frustrated by what I can't comprehend, help me worship You for it. I don't need to figure You out — I need to trust You. I rest in a God who is bigger than my mind can contain. In Jesus' name, amen.",
            reflectionPrompt: "Is there a situation where you need to trust God's higher ways instead of demanding an explanation?",
            actionSteps: ["Identify one situation you don't understand and choose to trust God's higher wisdom", "Spend time in worship focused on God's greatness and mystery"]
        ),
        DayContent(
            scriptureReference: "James 4:8",
            scriptureText: "Come near to God and he will come near to you.",
            devotionalTitle: "He Meets You Halfway",
            devotionalText: "This is one of the most encouraging promises in Scripture: when you take a step toward God, He takes a step toward you. You don't have to cover the whole distance. You don't have to earn His approach. Just come near. Open your Bible — He'll speak. Start praying — He'll listen. Seek Him — He'll be found. God is not far from anyone who reaches for Him.",
            prayerText: "Lord, I come near to You today. I take a step, and I trust You to meet me. Remove anything that creates distance between us. I want to be close — not just in theory, but in daily experience. Draw near to me as I draw near to You. In Jesus' name, amen.",
            reflectionPrompt: "What step can you take today to come nearer to God?",
            actionSteps: ["Take one concrete step toward God today: pray, read, worship, or sit in silence", "Remove one thing that creates distance between you and God"]
        ),
        DayContent(
            scriptureReference: "Psalm 19:1-2",
            scriptureText: "The heavens declare the glory of God; the skies proclaim the work of his hands. Day after day they pour forth speech; night after night they reveal knowledge.",
            devotionalTitle: "God Never Stops Speaking",
            devotionalText: "Day after day. Night after night. Creation never stops declaring God's glory. There's no intermission, no commercial break, no silent day. God is constantly revealing Himself if you have eyes to see. The sunrise this morning was a sermon. The stars tonight will be a lecture. God is speaking all the time — through creation, through His Word, through His Spirit. Are you listening?",
            prayerText: "Lord, You never stop speaking. Creation pours forth speech about You day and night. Open my ears and eyes to the constant revelation of Your glory. I don't want to miss a single message. Speak, Lord — through creation, through Your Word, through Your Spirit. I'm listening. In Jesus' name, amen.",
            reflectionPrompt: "What is God saying to you through creation today?",
            actionSteps: ["Watch the sunrise or sunset today and listen for what God is saying through it", "Keep a 'God is speaking' journal — write down one way God reveals Himself to you each day this week"]
        ),
        DayContent(
            scriptureReference: "Hosea 6:3",
            scriptureText: "Let us acknowledge the Lord; let us press on to acknowledge him. As surely as the sun rises, he will appear; he will come to us like the winter rains, like the spring rains that water the earth.",
            devotionalTitle: "Press On to Know Him",
            devotionalText: "Knowing God is not passive. Hosea says press on. Pursue. Don't settle for surface-level acquaintance. The promise is beautiful: as surely as the sun rises, He will appear. God rewards persistent seekers. If you press on, He will come to you like refreshing rain. Keep seeking. He's worth the pursuit.",
            prayerText: "Lord, I press on to know You. I won't settle for shallow faith or distant religion. I want the deep, refreshing experience of Your presence. Come to me like rain on dry ground. As surely as the sun rises, I trust You will appear. I press on. In Jesus' name, amen.",
            reflectionPrompt: "Are you pressing on in your knowledge of God, or have you plateaued?",
            actionSteps: ["Choose one new spiritual discipline to try this week as a way of pressing deeper", "Set a specific daily time for seeking God and guard it this week"]
        ),
        DayContent(
            scriptureReference: "Colossians 1:15-17",
            scriptureText: "The Son is the image of the invisible God, the firstborn over all creation. For in him all things were created: things in heaven and on earth, visible and invisible. He is before all things, and in him all things hold together.",
            devotionalTitle: "The God Who Holds Everything Together",
            devotionalText: "In Christ, all things hold together. Your life, the universe, every atom and galaxy — held together by the One you're getting to know. This isn't a distant, detached deity. This is a God who is intimately involved in sustaining everything, including you. The same power that holds galaxies in orbit is holding your life together right now.",
            prayerText: "Lord Jesus, You hold all things together — including me. When my life feels like it's falling apart, remind me that Your hands are holding everything in place. You are before all things and over all things. I rest in Your sustaining power today. In Jesus' name, amen.",
            reflectionPrompt: "Where in your life do you need to remember that God is holding things together?",
            actionSteps: ["When you feel overwhelmed today, whisper 'He holds all things together'", "Read Colossians 1:15-20 and worship the God described in these verses"]
        ),
        DayContent(
            scriptureReference: "Psalm 103:8-10",
            scriptureText: "The Lord is compassionate and gracious, slow to anger, abounding in love. He will not always accuse, nor will he harbor anger forever; he does not treat us as our sins deserve or repay us according to our iniquities.",
            devotionalTitle: "Better Than You Deserve",
            devotionalText: "God doesn't treat you as your sins deserve. Let that sink in. He's not keeping a tab. He's not building a case. He's compassionate when you expect judgment, gracious when you expect punishment. Knowing God means discovering that He is far kinder than you imagined. Every encounter with His grace rewrites your expectations.",
            prayerText: "Lord, You are more compassionate than I imagined, more gracious than I deserve. Thank You for not treating me as my sins deserve. Your love overwhelms my failure. Help me know You as the God of grace — not the God of my guilty imagination. In Jesus' name, amen.",
            reflectionPrompt: "Do you relate to God based on who He actually is, or based on who you imagine Him to be?",
            actionSteps: ["Write down one area where you've expected judgment from God and replace it with His grace", "Extend the same kind of grace to someone today that God extends to you"]
        ),
        DayContent(
            scriptureReference: "John 14:9",
            scriptureText: "Jesus answered: 'Don't you know me, Philip, even after I have been among you such a long time? Anyone who has seen me has seen the Father.'",
            devotionalTitle: "Have You Been With Him This Long?",
            devotionalText: "Philip asked to see the Father, and Jesus was surprised. After all their time together, Philip still didn't see it. Jesus IS the revelation of the Father. Sometimes we look for God everywhere except in Jesus. We want mystical experiences when God has given us the Gospels. Knowing Jesus IS knowing God. Don't overcomplicate it.",
            prayerText: "Jesus, I see the Father in You. When I read about Your compassion, I see God's heart. When I hear Your words, I hear God's voice. Help me not look past You for some other revelation. You are enough. Knowing You is knowing the Father. In Jesus' name, amen.",
            reflectionPrompt: "Have you been looking for God while overlooking Jesus?",
            actionSteps: ["Read one Gospel story today and ask 'What does this show me about God?'", "Make the Gospels your primary window into God's character this week"]
        ),
        DayContent(
            scriptureReference: "Psalm 34:8",
            scriptureText: "Taste and see that the Lord is good; blessed is the one who takes refuge in him.",
            devotionalTitle: "Experience, Don't Just Study",
            devotionalText: "You can read about honey without ever tasting it. You can study God without ever experiencing Him. The psalmist invites you to taste — to experience God's goodness firsthand. Head knowledge about God is good, but it's no substitute for personal encounter. Knowing God is experiential. You have to taste for yourself.",
            prayerText: "Lord, I don't just want to study You — I want to taste Your goodness. Give me a personal experience of who You are today. Move from my head to my heart. I take refuge in You and trust that You are good — not because someone told me, but because I've tasted it. In Jesus' name, amen.",
            reflectionPrompt: "Is your knowledge of God more intellectual or experiential? How can you deepen the experiential side?",
            actionSteps: ["Ask God for a personal experience of His goodness today — then watch for it", "Share one way you've tasted God's goodness with someone who needs encouragement"]
        ),
        DayContent(
            scriptureReference: "Proverbs 9:10",
            scriptureText: "The fear of the Lord is the beginning of wisdom, and knowledge of the Holy One is understanding.",
            devotionalTitle: "Reverence Opens the Door",
            devotionalText: "The fear of the Lord isn't terror — it's reverence, awe, and wonder. It's recognizing who God is and responding appropriately. This kind of holy respect is the starting point for real wisdom and understanding. When you approach God with awe instead of casualness, doors of understanding open that were previously closed.",
            prayerText: "Lord, fill me with holy reverence. Help me approach You with awe and wonder, not casual familiarity. I want the wisdom that comes from truly fearing You — not with terror, but with deep respect for who You are. Let the fear of the Lord be the foundation of my understanding. In Jesus' name, amen.",
            reflectionPrompt: "Do you approach God more with casual familiarity or with reverent awe?",
            actionSteps: ["Spend time in worship today focused on God's majesty and holiness", "Read Isaiah 6:1-8 and let Isaiah's response to God's holiness shape your own"]
        ),
        DayContent(
            scriptureReference: "2 Peter 3:18",
            scriptureText: "But grow in the grace and knowledge of our Lord and Savior Jesus Christ. To him be glory both now and forever! Amen.",
            devotionalTitle: "Never Stop Growing",
            devotionalText: "Peter's last words in his letter are a call to keep growing — in grace and in knowledge of Jesus. Knowing God isn't a destination you arrive at; it's a journey that never ends. There's always more to discover, more to experience, more to understand. No matter how long you've walked with God, the best is still ahead. Keep growing.",
            prayerText: "Lord Jesus, I want to keep growing in my knowledge of You. No matter how much I know, there's infinitely more. Keep me hungry, keep me curious, keep me pressing in. I never want to stop discovering who You are. To You be glory now and forever. In Jesus' name, amen.",
            reflectionPrompt: "In what specific area of knowing God do you want to grow next?",
            actionSteps: ["Set a growth goal for your relationship with God this month", "Ask a mature believer what they've learned about God recently that surprised them"]
        ),
    ]
}
